// 输入护栏：提示注入 / 越狱 / PII 预脱敏
const input = $json.body.prompt || '';
const injectionPatterns = [/ignore\s+(all\s+)?previous\s+instructions/i, /you\s+are\s+now\s+dan\b/i, /developer\s+mode/i, /pretend\s+you\s+are/i, /reveal\s+(your\s+)?system\s+prompt/i];
let risk = 0.0;
const reasons = [];
for (const re of injectionPatterns) { if (re.test(input)) { risk = Math.max(risk, 0.9); reasons.push('injection:' + re.source); } }
const sanitized = input
  .replace(/[\w.+-]+@[\w-]+\.[\w.]+/g, '[EMAIL]')
  .replace(/\b\d{17}[\dXx]\b/g, '[ID_CARD]')
  .replace(/\b(?:\d[ -]*?){13,19}\b/g, '[CARD]');
return [{ json: { sanitized, risk, reasons, action: risk >= 0.85 ? 'BLOCK' : (risk >= 0.6 ? 'REVIEW' : 'PASS') } }];

// 输出护栏：密钥 / PII / 有害内容扫描
const text = $json.text || JSON.stringify($json);
const secretPatterns = [/sk-[A-Za-z0-9]{16,}/g, /ghp_[A-Za-z0-9]{20,}/g, /AKIA[0-9A-Z]{16}/g, /-----BEGIN [A-Z ]*PRIVATE KEY-----/g];
let out = text;
let risk = 0.0;
const reasons = [];
for (const re of secretPatterns) { if (re.test(out)) { out = out.replace(re, '[REDACTED]'); risk = Math.max(risk, 0.9); reasons.push('secret_leak'); } }
if (/rm\s+-rf\s+\/|sudo\s+su\b/i.test(out)) { risk = Math.max(risk, 0.8); reasons.push('dangerous_command'); }
return [{ json: { sanitized: out, risk, reasons, action: risk >= 0.85 ? 'BLOCK' : (risk >= 0.6 ? 'REVIEW' : 'PASS') } }];

// 工具权限校验
const deny = ['shell_exec', 'sudo', 'file_delete', 'credential_dump'];
const requested = ($json.body.requested_tools || []);
const blocked = requested.filter(t => deny.includes(t));
return [{ json: { blocked_tools: blocked, allowed: blocked.length === 0 } }];

// 审计留痕（追加写）
const entry = { ts: new Date().toISOString(), risk: $json.risk, action: $json.action, reasons: $json.reasons };
require('fs').appendFileSync('/tmp/safety_audit.jsonl', JSON.stringify(entry) + '\n');
return [{ json: entry }];
